function toArticle(row: Row, detailType: PortalDetailType = 'article'): PortalArticle {
  const id = first(row.richTextId, row.id, row.msgId, row.problemId, row.videoId)
  const title = first(row.title, row.msgTitle, row.problemTitle, row.problemName)
  const publish = first(row.publishTime, row.createTime, row.publishDate)
  const read = first(row.readNum, row.viewCount, row.learnNum, row.studyNum)
  return remember({
    id, title,
    tag: first(row.typeName, row.tagName) || undefined,
    meta: dateOnly(publish) || first(row.source, row.publishUser),
    trailing: read ? `${read}阅读` : undefined,
    image: resolveMedia(first(row.previewSite, row.coverImage, row.coverImg, row.iconPath)) || undefined,
    source: first(row.source, row.publishUnit, row.publishUser) || undefined,
    publishTime: dateTime(publish) || undefined,
    summary: first(row.summary, row.abstract, row.description) || undefined,
    detailType,
    linkUrl: first(row.urlSite, row.linkUrl) || undefined,
    raw: row,
  })
}

tool_input.new_string:
function toArticle(row: Row, detailType: PortalDetailType = 'article', includeSourceMeta = false): PortalArticle {
  const id = first(row.richTextId, row.id, row.msgId, row.problemId, row.videoId)
  const title = first(row.title, row.msgTitle, row.problemTitle, row.problemName)
  const publish = first(row.publishTime, row.createTime, row.publishDate)
  const learned = first(row.learnNum, row.studyNum, row.studyCount, row.learningCount)
  const read = first(row.readNum, row.viewCount, row.readCount, row.browseNum)
  const source = first(row.source, row.publishUnit, row.publishUser)
  const publishDate = dateOnly(publish)
  const duration = first(row.durationText, row.duration, row.videoDuration)
  const meta = includeSourceMeta
    ? [source, publishDate].filter(Boolean).join(' · ')
    : publishDate || duration
  return remember({
    id, title,
    tag: first(row.typeName, row.tagName, row.categoryName) || undefined,
    meta,
    trailing: learned ? `${learned}次学习` : read ? `${read}阅读` : undefined,
    image: resolveMedia(first(row.previewSite, row.coverImage, row.coverImg, row.coverUrl, row.iconPath)) || undefined,
    source: source || undefined,
    publishTime: dateTime(publish) || undefined,
    summary: first(row.summary, row.abstract, row.description) || undefined,
    detailType,
    linkUrl: first(row.urlSite, row.linkUrl) || undefined,
    raw: row,
  })
}
